```rust
pub(crate) fn cmd_submit(
    workflow: &std::path::Path,
    input_bin: &std::path::Path,
    db: &std::path::Path,
    durability: DurabilityMode,
    output: OutputFormat,
) -> ExitCode {
    let input_data = match read_file(input_bin, output, CliExitCode::ValidationFailed) {
        Ok(b) => b,
        Err(code) => return code,
    };

    let bytes = match read_file(workflow, output, CliExitCode::ValidationFailed) {
        Ok(b) => b,
        Err(code) => return code,
    };

    let compiled = match vb_compile::compile_workflow(&bytes) {
        Ok(c) => c,
        Err(errors) => {
            // ... error handling ...
            return CliExitCode::CompileFailed.into();
        }
    };

    if let Err(error) = map_runtime_inputs(&compiled, &input_data) {
        write_failure_message(&error.to_string(), output, CliExitCode::ValidationFailed);
        return CliExitCode::ValidationFailed.into();
    }

    // Rest of submit computes digest then FjallJournal::open, source write, header write, event write; unchanged.
}
```

